{
  networking.hostName = "node17";
  networking.firewall.enable = false;
  networking.hosts = {
    "127.0.0.1" = [ "catalog.node.test" "sql.node.test" "cache.node.test" ];
  };

  time.timeZone = "Etc/UTC";
  i18n.defaultLocale = "C.UTF-8";

  # Accounts: same names, UIDs, GIDs, and locked passwords as the reference.
  users.groups = {
    amber = { gid = 1000; };
    cobalt = { gid = 1001; };
    tenants = { gid = 1002; members = [ "amber" "cobalt" ]; };
    www-data = { gid = 33; };
    adm = { gid = 4; members = [ "syslog" ]; };
    memcache = { gid = 122; };
  };
  users.users = {
    amber = {
      uid = 1101;
      group = "amber";
      isNormalUser = true;
      home = "/home/amber";
      homeMode = "755";
      createHome = true;
      hashedPassword = "!";
      shell = "/run/current-system/sw/bin/bash";
    };
    cobalt = {
      uid = 1102;
      group = "cobalt";
      isNormalUser = true;
      home = "/home/cobalt";
      homeMode = "755";
      createHome = true;
      hashedPassword = "!";
      shell = "/run/current-system/sw/bin/bash";
    };
    www-data = {
      uid = 33;
      group = "www-data";
      isSystemUser = true;
      home = "/var/www";
      shell = "/run/current-system/sw/bin/nologin";
    };
    memcache = {
      uid = 113;
      group = "memcache";
      isSystemUser = true;
      home = "/nonexistent";
      shell = "/run/current-system/sw/bin/nologin";
    };
  };
  users.users.root.hashedPassword = "!";

  # SSH: key-based root only, as in the reference.
  services.openssh = {
    enable = true;
    settings = {
      PermitRootLogin = lib.mkForce "prohibit-password";
      PasswordAuthentication = false;
      KbdInteractiveAuthentication = false;
      X11Forwarding = true;
      AcceptEnv = [ "LANG" "LC_*" ];
    };
  };

  # Sudo rules for the tenants.
  security.sudo.extraRules = [
    {
      users = [ "amber" ];
      runAs = "root:adm";
      commands = [
        { command = "${pkgs.coreutils}/bin/cat /var/log/web/amber-access.log"; options = [ "NOPASSWD" ]; }
        { command = "${pkgs.coreutils}/bin/cat /var/log/web/amber-error.log"; options = [ "NOPASSWD" ]; }
      ];
    }
    {
      users = [ "cobalt" ];
      runAs = "root:adm";
      commands = [
        { command = "${pkgs.coreutils}/bin/cat /var/log/web/cobalt-access.log"; options = [ "NOPASSWD" ]; }
        { command = "${pkgs.coreutils}/bin/cat /var/log/web/cobalt-error.log"; options = [ "NOPASSWD" ]; }
      ];
    }
    {
      users = [ "cobalt" ];
      runAs = "root";
      commands = [
        { command = "/run/current-system/sw/bin/systemctl restart apache2"; options = [ "NOPASSWD" ]; }
      ];
    }
  ];

  # Apache, served by a unit named apache2 with the reference's vhosts.
  environment.etc = {
    "apache2/httpd.conf".source = httpdConf;
    "apache2/sites-enabled/amber.conf".source = ./web/amber.conf;
    "apache2/sites-enabled/cobalt.conf".source = ./web/cobalt.conf;
    "apache2/sites-enabled/node.conf".source = ./web/node.conf;
  };
  systemd.services.apache2 = {
    description = "The Apache HTTP Server";
    wantedBy = [ "multi-user.target" ];
    after = [ "network.target" "php-fpm-amber.service" "php-fpm-cobalt.service" ];
    wants = [ "php-fpm-amber.service" "php-fpm-cobalt.service" ];
    path = [ pkgs.coreutils ];
    serviceConfig = {
      Type = "simple";
      RuntimeDirectory = "apache2";
      ExecStartPre = "${apache}/bin/httpd -t -f /etc/apache2/httpd.conf";
      ExecStart = "${apache}/bin/httpd -f /etc/apache2/httpd.conf -DFOREGROUND";
      ExecReload = "${apache}/bin/httpd -f /etc/apache2/httpd.conf -k graceful";
      ExecStop = "${apache}/bin/httpd -f /etc/apache2/httpd.conf -k graceful-stop";
      KillMode = "mixed";
      KillSignal = "SIGWINCH";
      Restart = "on-failure";
    };
  };

  # PHP-FPM pools per tenant (socket paths as in the reference).
  services.phpfpm.pools = {
    amber = phpPool "amber" 1101;
    cobalt = phpPool "cobalt" 1102;
