    PSQL="${config.services.postgresql.package}/bin/psql"
    $PSQL -tA -c "ALTER ROLE amber CONNECTION LIMIT 20 PASSWORD 'SCRAM-SHA-256\$4096:1rJz1zqG8QX/Y9iyLfy+lA==\$xiy0NZkFo/LAtz2nXOGKIe2zVKP/vQRkaWaOjY+I4Bs=:erHpSa6MlYgT5C+t+fyUrzYeTASwOPfh/4ctsI3JRbQ='"
    $PSQL -tA -c "ALTER ROLE cobalt CONNECTION LIMIT 40 PASSWORD 'SCRAM-SHA-256\$4096:0uFjL0lkmELvx5f9FwpW+w==\$qqQzU/nP3uNK/vLoe1X7N6sppcWN8hJ7U8Hi1pYp+Ws=:TFrV6ScYH+rMr+DnKDmtpLofLmo94TnqPL3iJIUyguU='"
    $PSQL -d amber -tA -c "CREATE EXTENSION IF NOT EXISTS postgis"
